#!/usr/bin/env python3
"""
Round 121b (culprits), 1 October 2026. Needs round 120b.

The soy traders and the Forest 500 banks and investors coloured by money.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''
NOTE = '## Round 121b (1 October)\n\nNeeds round 120b. Tiles patch round121b_tiles.py beside it. No app.js?v= bump.\n\n- Soy coloured by money (asked "colour soy by $ and influence", "yes to both"):\n  soy_traders_money (the 24 trader offices, coloured by each trader\'s revenue\n  from Wikidata, then by trader) and forest500_soy_money (the 70 banks and\n  investors, coloured by the financing in Forest 500\'s own data download once\n  the owner puts it in culprits-tiles-more forest500/download/, else by soy\n  score). Both read files built by scripts/soy_money.py. They replace\n  site_soybean_companies and site_forest500_soy in Nitrous oxide > Crops and\n  Agriculture > Soy; the old rows are in PANEL_REMOVED.\n- Not done yet: ESDAC Global Soil Biodiversity maps (permission granted with a\n  citation; the files come only through ESDAC\'s form and may not be passed to\n  third parties, so they will be drawn as pictures once the owner attaches them).\n- test.mjs: round 121b block.\n\n'
HEAD = "## Round 121b (1 October)"


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round121b: run from the culprits repository root")
    text = (root / "HANDOFF.md").read_text(encoding="utf-8")
    if "## Round 120b" not in text:
        sys.exit("round121b: round 120b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round121b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round121b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round121b: applied")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        # Above the newest note, whichever chat wrote it.
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
